delete from public.faqs;

insert into public.faqs (scope, question, answer, sort_order, published) values ('general', 'What does Al Saqr Al Ahmar fabricate?', 'Structural steel, pipeline components and supports, CNC-cut plate and sheet, storage containers such as tanks and silos, and stainless steel items such as handrails, ladders and gratings. Each service page lists the full scope.', 1, true);

insert into public.faqs (scope, question, answer, sort_order, published) values ('general', 'Where is your workshop, and which areas do you cover?', 'Our workshop is in the Elite Business Investment Zone, Musaffah Industrial 44, Abu Dhabi. We work on projects across the UAE — include your site location when you request a quote.', 2, true);

insert into public.faqs (scope, question, answer, sort_order, published) values ('general', 'Do you publish prices?', 'No. Every project is priced individually from its drawings and scope. Send a request and our team will review it and contact you.', 3, true);

insert into public.faqs (scope, question, answer, sort_order, published) values ('general', 'Can you prepare drawings and detailing?', 'Yes. Our engineering personnel prepare drawings and detailing on current design software before fabrication. Design responsibility for your project is agreed with our team as part of the quotation.', 4, true);

insert into public.faqs (scope, question, answer, sort_order, published) values ('general', 'Do you visit the site before quoting?', 'For larger or more complex scopes we can arrange a site visit. Mention it in your request and our team will confirm.', 5, true);

insert into public.faqs (scope, question, answer, sort_order, published) values ('quote', 'What should I include in a quotation request?', 'The service you need, the project location and a short description of the scope. Drawings, a bill of quantities (BOQ), site photographs, dimensions, quantities and your target date all help our team respond accurately.', 6, true);

insert into public.faqs (scope, question, answer, sort_order, published) values ('quote', 'Which files can I attach?', 'PDF, JPG and PNG files — up to 5 files, 10 MB each and 25 MB in total. For larger drawing sets, attach the key sheets and mention that more are available.', 7, true);

insert into public.faqs (scope, question, answer, sort_order, published) values ('quote', 'What happens after I submit?', 'You receive a reference number straight away. Our team reviews your request and contacts you by phone or email. For urgent work, call us directly.', 8, true);

insert into public.faqs (scope, question, answer, sort_order, published) values ('steel-structures', 'Do you install as well as fabricate?', 'Yes. Our scope covers fabrication and erection of structural steelwork. Describe the site conditions and access in your request.', 9, true);

insert into public.faqs (scope, question, answer, sort_order, published) values ('steel-structures', 'Can I send architectural drawings rather than shop drawings?', 'Yes. Send the drawings you have; our team will tell you what further information is needed for detailing and pricing.', 10, true);

insert into public.faqs (scope, question, answer, sort_order, published) values ('pipeline-welding', 'Do you work on onshore and offshore facilities?', 'Yes. Our pipeline work covers onshore and offshore oil and gas fields and facilities. Include the project specification with your request.', 11, true);

insert into public.faqs (scope, question, answer, sort_order, published) values ('laser-cnc-cutting', 'Which cutting method will you use?', 'CNC water jet, laser, sheet perforation or oxy-fuel cutting, depending on the material and thickness. Tell us the material, thickness and quantity and our team will advise.', 12, true);

insert into public.faqs (scope, question, answer, sort_order, published) values ('storage-containers', 'Which storage items do you fabricate?', 'Fuel tanks, cement silos, skips, tube tanks and water foundation facilities, including DNV onshore and offshore items. Share the specification your project requires.', 13, true);

insert into public.faqs (scope, question, answer, sort_order, published) values ('stainless-steel', 'Which stainless steel items do you fabricate?', 'Handrails, ladders, table panels and gratings, as well as containers, tanks, baskets and skids.', 14, true);

