insert into public.process_steps (title, body, sort_order, published) values ('Enquiry and documents', 'Send the scope, site location and any drawings, BOQ or site photographs you have.', 1, true);

insert into public.process_steps (title, body, sort_order, published) values ('Review and site visit', 'Our team reviews the information and, where the scope needs it, arranges a site visit.', 2, true);

insert into public.process_steps (title, body, sort_order, published) values ('Quotation', 'We prepare a quotation. Price, programme and terms are confirmed by our team in writing.', 3, true);

